  "implementation": "def solve(case):
    word_token_indices = case.get('word_token_indices')
    word_labels = case.get('word_labels')
    token_count = case.get('token_count')
    if word_token_indices is None or word_labels is None or token_count is None:
        raise ValueError('Missing required fields')
    if not isinstance(word_token_indices, list) or not isinstance(word_labels, list) or not isinstance(token_count, int):
        raise ValueError('Invalid types')
    if len(word_token_indices) != len(word_labels):
        raise ValueError('Mismatched lengths')
    token_label = [None] * token_count
    for indices, label in zip(word_token_indices, word_labels):
        for idx in indices:
            if not isinstance(idx, int):
                raise ValueError('Non-integer index')
            if idx < 0 or idx >= token_count:
                raise ValueError(f'Index {idx} out of range')
            if token_label[idx] is not None:
                raise ValueError(f'Overlapping index {idx}')
            token_label[idx] = label
    for i, lbl in enumerate(token_label):
        if lbl is None:
            raise ValueError(f'Uncovered token index {i}')
    kept_indices = [i for i, lbl in enumerate(token_label) if lbl == 1]
    return {'kept_indices': kept_indices, 'token_labels': token_label}"
}
